-- CHECK constraints for ranges the spec fixes.
ALTER TABLE "news_items" ADD CONSTRAINT "news_items_tone_check" CHECK ("tone" IS NULL OR "tone" BETWEEN -100 AND 100);
ALTER TABLE "fear_greed_daily" ADD CONSTRAINT "fear_greed_daily_value_check" CHECK ("value" BETWEEN 0 AND 100);
ALTER TABLE "profiles" ADD CONSTRAINT "profiles_knowledge_check" CHECK ("knowledge" IS NULL OR "knowledge" BETWEEN 1 AND 4);
ALTER TABLE "signals" ADD CONSTRAINT "signals_code_check" CHECK ("code" ~ '^SG([1-9]|1[0-4])$');
ALTER TABLE "key_levels" ADD CONSTRAINT "key_levels_zone_check" CHECK ("low" <= "high");
ALTER TABLE "scores_daily" ADD CONSTRAINT "scores_daily_range_check" CHECK ("quality" BETWEEN 0 AND 100 AND "timing" BETWEEN 0 AND 100 AND "combined" BETWEEN 0 AND 100 AND ("usage" IS NULL OR "usage" BETWEEN 0 AND 100) AND ("earnings" IS NULL OR "earnings" BETWEEN 0 AND 100) AND ("supply" IS NULL OR "supply" BETWEEN 0 AND 100) AND ("access" IS NULL OR "access" BETWEEN 0 AND 100) AND ("safety" IS NULL OR "safety" BETWEEN 0 AND 100));
ALTER TABLE "sector_heat_daily" ADD CONSTRAINT "sector_heat_daily_range_check" CHECK ("heat" BETWEEN 0 AND 100 AND "pending_days" >= 0);
ALTER TABLE "narrative_heat_daily" ADD CONSTRAINT "narrative_heat_daily_range_check" CHECK ("heat" BETWEEN 0 AND 100 AND "pending_days" >= 0);
ALTER TABLE "market_weather_daily" ADD CONSTRAINT "market_weather_daily_score_check" CHECK ("score" BETWEEN -100 AND 100);
ALTER TABLE "alt_season_daily" ADD CONSTRAINT "alt_season_daily_score_check" CHECK ("score" BETWEEN 0 AND 100);
ALTER TABLE "base_rates" ADD CONSTRAINT "base_rates_n_check" CHECK ("n" >= 0);
ALTER TABLE "holdings" ADD CONSTRAINT "holdings_amount_check" CHECK ("amount" IS NULL OR "amount" >= 0);
ALTER TABLE "quick_checks" ADD CONSTRAINT "quick_checks_correct_index_check" CHECK (CASE WHEN jsonb_typeof("options") = 'array' THEN "correct_index" >= 0 AND "correct_index" < jsonb_array_length("options") ELSE false END);

-- events_calendar dedupe for market-wide rows: Postgres treats NULL asset_id values as
-- distinct, so the Prisma unique (asset_id, date, kind, title) cannot stop two market-wide
-- duplicates. This partial unique index does.
CREATE UNIQUE INDEX "events_calendar_market_wide_key" ON "events_calendar"("date", "kind", "title") WHERE "asset_id" IS NULL;
